1697	\begin{theorem}[Formalization support: positive-operator weighted Cauchy--Schwarz]
1698		\label{thm:complex-weighted-cauchy-schwarz}
1699		\lean{MIPStarRE.QPBT.norm_sum_inner_le_sqrt_mul_sqrt}
1700		\leanok
1701		\uses{def:distance-state-quadratic-form}
1702		Let $I$ and $J$ be finite sets, let $A_a$ be positive semidefinite
1703		operators on $\mathbb C^J$ for $a\in I$, and let $u_a,v_a\in\mathbb C^J$.
1704		Then
1705		\[
1706			\left|\sum_{a\in I}\langle u_a,A_av_a\rangle\right|
1707			\le
1708			\sqrt{\sum_{a\in I}\Re\langle u_a,A_au_a\rangle}
1709			\sqrt{\sum_{a\in I}\Re\langle v_a,A_av_a\rangle}.
1710		\]
1711	\end{theorem}
1712	\begin{proof}
1713		\leanok
1714		\uses{def:distance-state-quadratic-form}
1715		The triangle inequality bounds the modulus by the sum of the moduli.
1716		For each positive operator $A_a$, Cauchy--Schwarz for its positive
1717		sesquilinear form bounds the summand by
1718		$\sqrt{\Re\langle u_a,A_au_a\rangle}
1719		\sqrt{\Re\langle v_a,A_av_a\rangle}$.
1720		Apply the scalar Cauchy--Schwarz inequality to this finite sum.
1721	\end{proof}
