1723	\begin{theorem}[Formalization support: complex overlap deficit for projections]
1724		\label{thm:complex-projection-overlap-deficit}
1725		\lean{MIPStarRE.QPBT.norm_overlap_gap_le_sqrt_one_sub_of_isProj}
1726		\leanok
1727		\uses{def:povm-conventions, def:distance-state-quadratic-form}
1728		Let $\mu$ be a finitely supported probability law on a set $X$, and
1729		let $I,J$ be finite sets. For each $x\in X$, let $(A_{x,a})_{a\in I}$
1730		be a complete measurement on $\mathbb C^J$. Let $\psi\in\mathbb C^J$
1731		have norm one. Suppose $B_{x,a}$ and $C_{x,a}$ are orthogonal
1732		projections, each commuting with $A_{x,a}$, for all $x,a$.
1733		No commutation between $B_{x,a}$ and $C_{x,a}$ is required. Then
1734		\begin{align*}
1735			\Big|\E_{x\sim\mu}\sum_a
1736			\langle\psi,A_{x,a}C_{x,a}B_{x,a}\psi\rangle
1737			&-\E_{x\sim\mu}\sum_a
1738			\langle\psi,A_{x,a}C_{x,a}\psi\rangle\Big| \\
1739			&\le \sqrt{1-\E_{x\sim\mu}\sum_a
1740			\Re\langle\psi,A_{x,a}B_{x,a}\psi\rangle}.
1741		\end{align*}
1742	\end{theorem}
1743	\begin{proof}
1744		\leanok
1745		\uses{thm:complex-weighted-cauchy-schwarz, def:povm-conventions,
1746			def:distance-state-quadratic-form}
1747		For each $x$, apply Theorem~\ref{thm:complex-weighted-cauchy-schwarz}
1748		with weight $A_{x,a}$ and vectors $C_{x,a}\psi$ and
1749		$(I-B_{x,a})\psi$. Commutation, projectivity, and completeness bound
1750		the first quadratic sum by one and identify the second with
1751		$g(x)=1-\sum_a\Re\langle\psi,A_{x,a}B_{x,a}\psi\rangle\ge0$.
1752		The triangle inequality for the probability average followed by
1753		$\E_\mu\sqrt{g}\le\sqrt{\E_\mu g}$ gives the asserted bound.
1754	\end{proof}
