1821			\E_{(x,z,\alpha,\beta) \in \ell}
1822			&\sum_{f_X,f_Z} \bra{\hat\psi}
1823			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
1824			\big(\hat{M}^{(\mathrm{Point},Z),z}_{f_Z(z)} \,
1825			\hat{M}^{(\mathrm{Point},X),x}_{f_X(x)}
1826			\big)_{\mathsf{B}\mathsf{A}''}
