1830	\begin{proof}
1831		\uses{lem:qld-4-10, lem:qld-4-10-same-placement, lem:qld-sublines,
1832			lem:qld-xz-lines, lem:overlap-gap-distance,
1833			lem:qld-sublines-uniform-point, def:line-point-dist}
